def apply_slow_budget(
    cls,
    config: pytest.Config,
    items: list[pytest.Item],
) -> None:
    """Apply the shared slow budget independently of static enforcement.

    Raises:
        UsageError: If FLEXT slow timeout policy.

    """
    slow_timeout = cls.slow_budget_seconds(config)
    for item in items if slow_timeout is not None else ():
        if item.stash.get(cls.stash_budgeted, False):
            continue
        if item.get_closest_marker("slow") is None:
            continue
        if item.get_closest_marker("timeout") is not None:
            msg = (
                "FLEXT slow timeout policy: explicit pytest.mark.timeout is "
                f"forbidden; {item.nodeid} must use the config-owned slow budget"
            )
            raise pytest.UsageError(msg)
        item.stash[cls.stash_budgeted] = True
        if (
            item.get_closest_marker("slow") is not None
            and config.getoption("timeout") != 0
        ):
            item.add_marker(pytest.mark.timeout(slow_timeout), append=False)

def docker_compose_up(
    target: p.Tests.ContainerConfig,
    env_files: tuple[Path, ...],
    *,
    recreate: bool,
) -> p.Result[bool]:
    """Run compose up with --wait bounded by the target's startup timeout.

    Returns:
        The resulting ``p.Result[bool]``.

    """
    compose_file = target.compose_file
    if compose_file is None:
        return r[bool].fail(c.Tests.ERR_DOCKER_TARGET_NOT_INSPECTABLE)
    client = FlextTestsUtilitiesDockerClient.docker_compose_client(
        compose_file,
        target.project_name
        or FlextTestsUtilitiesDockerLifecycle.docker_compose_project(
            compose_file,
        ),
        env_files,
    )
    try:
        if recreate:
            client.compose.down(remove_orphans=True, volumes=True)
        client.compose.up(
            services=[target.service] if target.service else None,
            detach=True,
            remove_orphans=True,
            recreate=recreate,
            wait=True,
            wait_timeout=target.startup_timeout,
            quiet=True,
        )
    except c.Tests.DOCKER_COMPOSE_ERRORS as exc:
        return r[bool].fail_op("Compose up", exc)
    return r[bool].ok(value=True)

def _await_health(
    self,
    info: p.Tests.ContainerInfo,
    deadline: float,
    timeout: int,
) -> p.Result[p.Tests.ContainerInfo]:
    """Poll a starting healthcheck until it settles or the deadline passes.

    Returns:
        The resulting ``p.Result[p.Tests.ContainerInfo]``.

    """
    current = info
    while current.health == c.Tests.ContainerHealth.STARTING:
        if time.monotonic() >= deadline:
            return r[p.Tests.ContainerInfo].fail(
                c.Tests.ERR_DOCKER_READINESS_TIMEOUT.format(
                    name=current.name,
                    timeout=timeout,
                    detail="healthcheck still starting",
                ),
                error_code=c.Tests.DockerErrorCode.READINESS_TIMEOUT,
            )
        time.sleep(c.Tests.DOCKER_HEALTH_POLL_SECONDS)
        refreshed = self.fetch_container_info(current.name)
        if refreshed.failure:
            return refreshed
        current = refreshed.value
    return r[p.Tests.ContainerInfo].ok(current)
